<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { get } from '../api'
import type { Anomalies,Anomaly,Heat } from '../api'
import { filters,selectCell,selection } from '../store'
const props=defineProps<{revision:number;resetKey:number}>()
const emit=defineEmits<{evidence:[id:string]}>()
const reference=ref<Heat>()
const data=ref<Anomalies>(),chosen=ref<Anomaly>(),error=ref('')
let request=0
async function load(){const current=++request;try{const result=await get<Anomalies>('temporal/anomalies',filters.value);if(current===request)data.value=result}catch(e){if(current===request)error.value=(e as Error).message}}
watch(()=>props.revision,load,{immediate:true})
watch(()=>props.resetKey,()=>chosen.value=undefined)
async function inspect(row:Anomaly){chosen.value=row;selectCell(row.date,row.hour);selection.messageIds=row.message_ids;try{reference.value=await get<Heat>('temporal/heatmap',{start:'2040-10-01',end:'2040-10-14',entity_id:selection.entity,q:selection.q})}catch(e){error.value=(e as Error).message}}
const comparison=computed(()=>reference.value?.cells.filter(c=>c.hour===chosen.value?.hour)||[])
const comparisonMax=computed(()=>Math.max(1,...comparison.value.map(c=>c.count)))
const labels:Record<string,string>={volume_burst:'通信量偏离',new_contact_ratio:'首次出现主体占比',repeated_pair_ratio:'重复方向对集中度'}
</script>
<template><div class="anomaly-view"><div class="anomaly-header"><span>探索性异常提示</span></div><div v-if="error" class="error">{{error}}</div><div class="anomaly-list"><button v-for="row in data?.items.slice(0,5)" :key="row.date+row.hour" data-testid="anomaly-marker" @click="inspect(row)"><span :class="['signal',row.flagged?'flagged':'']"></span><span>{{row.date.slice(5)}} {{String(row.hour).padStart(2,'0')}}:00</span><b>{{row.count}} 条</b><span>基线 {{row.baseline}}</span><span class="score">{{row.score.toFixed(2)}}</span></button><div v-if="!data?.items.length" class="muted">当前范围没有可比较的通信。</div></div><div v-if="chosen" class="anomaly-explanation" data-testid="anomaly-explanation"><div class="baseline-plot" v-if="comparison.length"><h4>同小时通信量对比</h4><svg viewBox="0 0 728 122" data-testid="anomaly-baseline" aria-label="异常时段与其他日期同小时比较"><line x1="10" x2="720" :y1="94-chosen.baseline/comparisonMax*72" :y2="94-chosen.baseline/comparisonMax*72" stroke="#b48243" stroke-dasharray="4 3"/><g v-for="(c,i) in comparison" :key="c.date"><rect :x="i*51+14" :y="94-c.count/comparisonMax*72" width="30" :height="Math.max(1,c.count/comparisonMax*72)" :fill="c.date===chosen.date?'#b48243':'#91b6c9'"/><text :x="i*51+29" :y="88-c.count/comparisonMax*72" text-anchor="middle" font-size="11" fill="#5c6c76">{{c.count}}</text><text :x="i*51+29" y="113" text-anchor="middle" font-size="10" fill="#5c6c76">{{c.date.slice(5)}}</text></g></svg></div><p>{{chosen.date}} {{chosen.hour}} 时：{{chosen.count}} 条通信；其他 13 日同小时中位数 {{chosen.baseline}}，MAD {{chosen.mad}}。橙色柱标记当前选择。MAD 为 0 时用 max(1, √(中位数+1)) 缩放。标记条件：通信量正向 z ≥ 2.5。</p><div v-for="f in chosen.features" :key="f.name" class="feature"><span>{{labels[f.name]}}</span><span>特征 {{f.value.toFixed(3)}}</span><b>贡献 {{f.contribution.toFixed(3)}}</b></div><p>总分 = z + 0.5 × 首次出现主体占比 + 0.25 × 重复方向对集中度。首日不推断新增；首次出现只指观察窗口内。{{chosen.new_contacts.length?'首次出现主体：'+chosen.new_contacts.join('、'):'无可判定的新增主体。'}}</p><div class="anomaly-source"><span>原始通信：</span><button v-for="id in chosen.message_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button></div></div></div></template>
<style scoped>
.anomaly-view{border-top:1px solid var(--selected);padding:14px}.anomaly-header{display:flex;justify-content:space-between;gap:8px;font-size:12px;color:#9c793e;margin-bottom:10px}.anomaly-header>span:last-child{font-size:12px;color:var(--muted)}.anomaly-list{display:flex;flex-wrap:wrap;gap:6px}.anomaly-list>button{display:flex;align-items:center;gap:6px;background:#faf8f3;border:1px solid #e4dac6;font-size:12px;padding:6px 8px;color:var(--muted)}.signal{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--muted)}.signal.flagged{background:var(--gold)}.anomaly-list b{font-weight:500;color:var(--muted)}.score{color:#a37c37}.anomaly-explanation{font-size:12px;line-height:1.9;color:var(--muted);margin-top:14px;border-top:1px solid var(--selected);padding-top:4px}.feature{display:flex;gap:12px;font-size:12px;padding:3px 0}.feature>span:first-child{min-width:130px;color:var(--muted)}.feature b{font-weight:500;color:#a37c37}.anomaly-source{display:flex;gap:6px;flex-wrap:wrap;max-height:110px;overflow:auto}.anomaly-source .link{font-size:12px}.baseline-plot h4{font-size:13px;font-weight:600;color:var(--ink);margin:12px 0}.baseline-plot svg{display:block;width:100%}
</style>
